from collections import deque


def alien_order(words):
    adjacency = {ch: set() for word in words for ch in word}
    in_degree = {ch: 0 for ch in adjacency}

    for first, second in zip(words, words[1:]):
        min_len = min(len(first), len(second))
        found_diff = False
        for i in range(min_len):
            if first[i] != second[i]:
                if second[i] not in adjacency[first[i]]:
                    adjacency[first[i]].add(second[i])
                    in_degree[second[i]] += 1
                found_diff = True
                break
        if not found_diff and len(first) > len(second):
            return ""

    queue = deque(sorted(ch for ch in in_degree if in_degree[ch] == 0))
    order = []
    while queue:
        ch = queue.popleft()
        order.append(ch)
        for nxt in sorted(adjacency[ch]):
            in_degree[nxt] -= 1
            if in_degree[nxt] == 0:
                queue.append(nxt)

    if len(order) != len(adjacency):
        return ""
    return "".join(order)
